def MaxPyramidSequence(N, a):
    ans = 0
    for k in range(1, max(a) + 1):
        left = 0
        right = N - 1
        current_length = 0
        while left <= right:
            if a[left] >= k and a[right] >= k:
                current_length = 2 * k - 1
                break
            if a[left] < k:
                left += 1
            if a[right] < k:
                right -= 1
        ans = max(ans, current_length)
    return ans
